.starting-world-shell .world-special-actions { display:grid; gap:7px; pointer-events:auto; }
.starting-world-shell .world-special-actions button {
  display:flex; align-items:center; justify-content:center; gap:7px;
  min-height:48px; background:#102d40ed; color:#f0ffff;
  border:1px solid #adede5; border-radius:12px; font-weight:750;
  touch-action:manipulation; user-select:none;
}
.starting-world-shell .world-special-actions button[aria-pressed=true] { background:#225748; border-color:#dcfff0; }
.starting-world-shell .world-special-actions button:disabled { opacity:.5; }
.starting-world-shell .world-special-actions button:focus-visible { outline:3px solid #fff; outline-offset:3px; }
@media (max-width:760px) {
  .starting-world-shell .world-special-actions { gap:6px; }
  .starting-world-shell .world-special-actions button { min-height:48px; font-size:.82rem; }
  .starting-world-shell .world-hint { max-width:calc(100% - 260px); }
}
@media (max-width:370px) { .starting-world-shell .world-hint { display:none; } }

import * as THREE from 'three'
import { riverHalfWidth } from './waterPhysics.ts'

/** Seeded, local scenery; one instanced draw, no images or external requests. */
export function createMeadowGrass(mobile: boolean) {
  const shape = new THREE.BufferGeometry()
  shape.setAttribute('position', new THREE.Float32BufferAttribute([
    -.04,0,0, .04,0,0, .015,.24,.02,
    0,0,-.04, 0,0,.04, -.015,.2,.02,
    -.025,0,-.025, .025,0,.025, .04,.17,0,
  ],3))
  shape.computeVertexNormals()
  const grass = new THREE.InstancedMesh(shape, new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 1, side: THREE.DoubleSide }), mobile ? 1200 : 2800)
  grass.name = 'meadow-grass-instanced'
  const dummy = new THREE.Object3D(), color = new THREE.Color()
  let seed = 73429
  const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296 }
  for (let i = 0; i < grass.count; i++) {
    const x = (random() - .5) * 70
    let z = (random() - .5) * 66
    // Keep water and the portal river line clear.
    if (Math.abs(z) < riverHalfWidth(x) + 1) z += Math.sign(z || 1) * (riverHalfWidth(x) + 1.5)
    dummy.position.set(x, .006, z)
    dummy.rotation.y = random() * Math.PI * 2
    const scale = .6 + random() * .65
    dummy.scale.set(scale, scale, scale); dummy.updateMatrix()
    grass.setMatrixAt(i, dummy.matrix)
    color.setHSL(.23 + random() * .07, .30 + random() * .12, .20 + random() * .12)
    grass.setColorAt(i, color)
  }
  grass.receiveShadow = true
  grass.computeBoundingSphere()
  return grass
}

